+        out.writeBoolean(canMatch);
+        if (out.getVersion().onOrAfter(Version.V_7_6_0)) {
+            out.writeOptionalWriteable(estimatedMinAndMax);
+        }
+    }
+
+    public boolean canMatch() {
+        return canMatch;
+    }
+
+    public MinAndMax<?> estimatedMinAndMax() {
+        return estimatedMinAndMax;
+    }
